function countWords(str) { 
  const matches = str.match(/\p{L}[\p{L}\p{N}_']*/gu);
  return matches ? matches.length : 0; 
} 
return [{ 
    json: { wordCount: Math.min(countWords($('Webhook').first().json.body.messages[0].body), 12) }   // reading pause ≤ 8 s (stage 3 delay budget) 
  }];

const wh = $('Webhook').first().json;
const triggeringId = wh.body.messages[0].id;
const triggeringChatId = wh.body.messages[0].chatId;

// Wappi/tapi CROSS concurrent same-endpoint responses (project-confirmed; the Unity client
// defends with CrossChatResponseGuard). Two chats bursting at once now issue messages/get
// concurrently from n8n too, so drop any row naming a FOREIGN chat before it can drive the
// is-latest decision or leak another chat's text into the combine. Conservative, mirroring
// CrossChatResponseGuard: a row with no chatId is KEPT (never discard on missing data), so a
// non-crossed fetch filters to itself and behavior is unchanged. A fully crossed payload
// filters to empty -> newestIncoming undefined -> abort (the pre-existing id-mismatch
// outcome: this fragment dead-ends; never a second reply).
const fetchedAll = ($json.messages || []).slice();
const isForeign = (m) => m && m.chatId && triggeringChatId && m.chatId !== triggeringChatId;
const fetched = fetchedAll.filter(m => !isForeign(m));
const foreignFetched = fetchedAll.length - fetched.length;

// Stable newest-first order: time desc, then Wappi's own order (newest first) breaks equal timestamps —
// two rows in the same second no longer shuffle on every fetch (stage 3).
fetched.forEach((m, i) => { if (m) m.__i = i; });
fetched.sort((a, b) => ((b.time || 0) - (a.time || 0)) || ((a.__i || 0) - (b.__i || 0)));

const isText = (m) => m && (m.type === 'chat' || m.type === 'text');
const incoming = fetched.filter(m => m && m.fromMe === false);
const newestIncoming = incoming[0];
// A3 (stage 3): an OWNER row newer than the trigger means the owner already answered (from the phone or
// the app) — an auto-reply on top of it is exactly the double reply the audit reproduced. Abort.
const trigIdx = fetched.findIndex(m => m && m.id === triggeringId);
const ownerReplied = trigIdx >= 0 && fetched.slice(0, trigIdx).some(m => m && m.fromMe === true);

let abort = false;
let combinedText = null;

if (!newestIncoming || newestIncoming.id !== triggeringId || ownerReplied) {
  abort = true;
} else if (isText(newestIncoming)) {
  const parts = [];
  for (const m of fetched) {
    if (m.fromMe === true) break;
    if (!isText(m)) break;
    parts.push(typeof m.body === 'string' ? m.body : '');
  }
  parts.reverse();
  // '' would beat the Text node's `?? $json.body.messages[0].body` fallback (?? is nullish-only)
  // and hand the agent an EMPTY prompt whenever the loop breaks on iteration 1 — e.g. a humanizer
  // reply to an earlier fragment lands inside this fragment's window. Stay nullish when empty.
  combinedText = parts.length > 0 ? parts.join('\n') : null;
}

// foreignFetched rides along purely as an observability flag: runData shows > 0 exactly when a
// crossed messages/get response reached this node.
// pairedItem is EXPLICIT (same idiom as the orchestrators' Vertical Prompt node): every node
// below the splice back-references the trigger with an .item lookup on the Webhook node, which
// needs an unbroken paired-item chain. Without it Mark Read / Typing / Chat Memory / send all
// depend on n8n's implicit auto-pairing surviving Wait -> HTTP -> Code -> If, and a break kills
// every reply with "paired item data unavailable".
return [{ json: { ...wh, abort, combinedText, foreignFetched }, pairedItem: { item: 0 } }];

const src = $('Latest+Combine').first().json;
const row = $input.first()?.json ?? {};
const failOpen = Boolean(row.error) || row.allowed === undefined;
return [{
  json: { ...src, allowed: failOpen ? true : row.allowed === true,
          quotaUsed: row.used ?? null, plan: row.plan ?? null, status: row.status ?? null, failOpen },
  pairedItem: { item: 0 },
}];

// OUTCOME STAMP (audit stage 0.5, Tools/n8n/apply-outcome-stamps.py). One structured row per
// execution end, no dialog text: the label is derived from WHICH branch reached this node.
const byPrev = { 'If': 'filtered', 'Suppressed?': 'suppressed', 'Is Latest?': 'superseded',
                 'If Quota Allows': 'quota_denied', 'HTTP Request': 'sent', 'Claimed?': 'duplicate',
                 'Is Outgoing?': 'ignored', 'Outgoing Bound?': 'filtered' };
const prev = $prevNode.name;
let wh = {};
try { wh = $('Webhook').first().json || {}; } catch (e) { wh = {}; }
const m = (wh.body && Array.isArray(wh.body.messages) && wh.body.messages[0]) || {};
const resp = $input.first() ? ($input.first().json || {}) : {};
// Stage 3: the record rows (Record Send / Record Cancel) carry the event's final state explicitly.
const outcome = (typeof resp.outcome === 'string' && resp.outcome) ? resp.outcome : (byPrev[prev] || ('other:' + prev));
return [{ json: {
  outcome,
  correlationId: $execution.id,
  stage: prev,
  messageId: m.id ?? null,
  profileId: m.profile_id ?? null,
  chatId: m.chatId ?? null,
  channel: 'telegram',
  transportMessageId: resp.transport_message_id ?? ((prev === 'HTTP Request' && resp && resp.message_id) ? resp.message_id : null),
  transportStatus: (prev === 'HTTP Request' && resp) ? (resp.status ?? null) : null,
  stampedAt: new Date().toISOString(),
}, pairedItem: { item: 0 } }];

// CANCEL LABEL: one place that names why a reply did not go out, from whichever gate refused it.
const j = $input.first().json || {};
const prev = $prevNode.name;
let outcome;
if (prev === 'Is Latest?') outcome = 'superseded';
else if (prev === 'If Quota Allows') outcome = 'quota_denied';
else if (prev === 'Generated?') outcome = 'generation_failed';
else if (prev === 'Final OK?') outcome = j.outcome || 'cancelled_fetch';
else if (prev === 'Send Allowed?') outcome = j.suppressed === true ? 'cancelled_mode' : (j.lock_busy === true ? 'cancelled_busy' : 'superseded');
else outcome = 'cancelled_fetch';
let watermark = 0;
try { watermark = Number($('Claim Event').first().json.history_watermark) || 0; } catch (e) { watermark = 0; }
// Only a run that reached the generator can have written an AI memory row to drop — and it drops ONLY ITS OWN
// row (R7/V6): Record Cancel deletes the row Stamp Draft tied to this execution id; aiText is the gate (no agent
// output, nothing to drop). The media branch (Ask to Send Text) reaches the same gates without running the agent —
// there $('AI Agent') throws, aiText stays null and nothing is dropped.
const generated = prev === 'Final OK?' || prev === 'Send Allowed?';
let aiText = null;
if (generated) {
  try { const o = $('AI Agent').first().json.output; aiText = (typeof o === 'string' && o.trim()) ? o : null; } catch (e) { aiText = null; }
}
// A6: when the agent never ran, the client's message still has to reach memory (it is the memory
// node that writes it on a normal run).
const recordHuman = prev === 'If Quota Allows' || prev === 'Generated?';
let humanText = '';
if (recordHuman) {
  try { humanText = String($('Audio').first().json.text || ''); } catch (e) { humanText = ''; }
  if (!humanText) { try { humanText = String($('Text').first().json.text || ''); } catch (e) { humanText = ''; } }
  if (!humanText) { try { humanText = String($('Latest+Combine').first().json.combinedText || ''); } catch (e) { humanText = ''; } }
  if (!humanText) { try { const m = $('Webhook').first().json.body.messages[0]; humanText = ['chat', 'text'].includes(String(m.type)) ? String(m.body || '') : '[' + String(m.type || 'media') + ']'; } catch (e) { humanText = ''; } }
}
return [{ json: { outcome, historyWatermark: watermark, dropAiHistory: generated && aiText !== null, aiText: aiText || '', recordHuman,
                  humanText: humanText.slice(0, 4000) }, pairedItem: { item: 0 } }];

// FINAL CHECK (A3, stage 3): re-read the chat RIGHT BEFORE sending. Same rules as Latest+Combine, on a
// fresh snapshot: a client message newer than the trigger → this text is stale (superseded — the newer
// event's own run answers); an owner message newer than the trigger → the owner took over (cancelled).
// A snapshot that does not even contain the trigger (crossed/short fetch) is never sent on.
const wh = $('Webhook').first().json;
const trig = wh.body.messages[0];
let claim = {};
try { claim = $('Claim Event').first().json || {}; } catch (e) { claim = {}; }
let text = '';
try { text = String($('Retrieve Answer').first().json.text || ''); } catch (e) {
  try { text = String($('Ask to Send Text').first().json.text || ''); } catch (e2) { text = ''; }
}
const fetchedAll = ($json.messages || []).slice();
const fetched = fetchedAll.filter(m => !(m && m.chatId && trig.chatId && m.chatId !== trig.chatId));
fetched.forEach((m, i) => { if (m) m.__i = i; });
fetched.sort((a, b) => ((b.time || 0) - (a.time || 0)) || ((a.__i || 0) - (b.__i || 0)));   // newest first, Wappi order breaks ties
const trigIdx = fetched.findIndex(m => m && m.id === trig.id);
let ok = true, outcome = null;
if (!text.trim()) { ok = false; outcome = 'generation_failed'; }
else if (trigIdx < 0) { ok = false; outcome = 'cancelled_fetch'; }
else if (fetched.slice(0, trigIdx).some(m => m && m.fromMe === false)) { ok = false; outcome = 'superseded'; }
else if (fetched.slice(0, trigIdx).some(m => m && m.fromMe === true)) { ok = false; outcome = 'cancelled_owner'; }
// V5 (iteration 2026-09-28): what this snapshot SAW, for the lease's same-second peer rule. The rule needs a
// snapshot COMPLETE for the trigger's second: messages/get returns at most 15 rows, so a full page whose every
// row is at or after that second (an album of more photos than fit) proves nothing about a row it lacks.
const seenIds = fetched.filter(m => m && m.id !== undefined && m.id !== null).map(m => String(m.id));
const seenComplete = fetchedAll.length < 15 || fetched.some(m => m && Number(m.time || 0) > 0 && Number(m.time || 0) < Number(trig.time || 0));
// The pass AFTER the lease asked for its one re-read (on the first pass the lease has not run: the reference throws).
let recheck = false;
try { recheck = $('Acquire Send Lease').first().json.peer_unseen === true; } catch (e) { recheck = false; }
return [{ json: { ok, outcome, text, generation: Number(claim.generation) || 0, historyWatermark: Number(claim.history_watermark) || 0,
                  sendStartedAt: Math.floor(Date.now() / 1000), seenIds, seenComplete, recheck }, pairedItem: { item: 0 } }];

// SETTLE SEND (A7): classify the transport call — never assume delivery from a missing answer.
const r = $input.first().json || {};
const body = (r.body && typeof r.body === 'object') ? r.body : {};
const status = Number(r.statusCode) || 0;
let state, transportMessageId = '', error = '';
if (!status && r.error) { state = 'send_unknown'; error = String(r.error.message || r.error).slice(0, 300); }
else if (status === 200 && (body.status === 'done' || body.message_id)) { state = 'sent'; transportMessageId = String(body.message_id || ''); }
else if (status >= 400 || body.status === 'error') { state = 'send_failed'; error = ('http ' + status + ' ' + JSON.stringify(body)).slice(0, 300); }
else { state = 'send_unknown'; error = ('unexpected ' + JSON.stringify(r)).slice(0, 300); }
const fc = $('Final Check').first().json;
return [{ json: { state, unknown: state === 'send_unknown', transportMessageId, error, text: fc.text, sendStartedAt: fc.sendStartedAt }, pairedItem: { item: 0 } }];

// RECONCILE (A7): the transport may have accepted the message although its answer was lost. Look for
// OUR text as an outgoing row after the send started; found ⇒ sent (adopt its id), else the state stays
// send_unknown for the owner to see. Never resend here.
// R10: Final Check's rules, stricter — here a false «sent» hides a lost reply. Rows naming a FOREIGN chat are
// dropped (Wappi/tapi cross concurrent responses); the window must hold the TRIGGER (a crossed window without
// chatId fields fails here); the echo must be newer than the trigger in the window's order (time desc, Wappi
// order on ties); a row the transport marks as sent from the phone (tapi from_where) is the owner's, not ours;
// and EXACTLY ONE distinct row may match — none or several (the owner typed the same text) stay send_unknown.
const s = $('Settle Send').first().json;
const trig = $('Webhook').first().json.body.messages[0];
const fetchedAll = ($json.messages || []).filter(m => m && typeof m === 'object');
const fetched = fetchedAll.filter(m => !(m.chatId && trig.chatId && m.chatId !== trig.chatId));
fetched.forEach((m, i) => { m.__i = i; });
fetched.sort((a, b) => ((b.time || 0) - (a.time || 0)) || ((a.__i || 0) - (b.__i || 0)));
const trigIdx = fetched.findIndex(m => m.id === trig.id);
const ours = m => m.fromMe === true && typeof m.body === 'string' && m.from_where !== 'phone'
  && m.body.trim() === String(s.text).trim() && (m.time || 0) >= (Number(s.sendStartedAt) - 5);
const cands = [];
for (const m of (trigIdx < 0 ? [] : fetched.slice(0, trigIdx))) {
  if (ours(m) && !cands.some(x => String(x.id) === String(m.id))) cands.push(m);
}
const hit = cands.length === 1 ? cands[0] : null;
const why = trigIdx < 0 ? 'reconcile: window without the trigger' : (cands.length > 1 ? 'reconcile: ambiguous echo (' + cands.length + ' rows)' : '');
return [{ json: { state: hit ? 'sent' : 'send_unknown', transportMessageId: hit ? String(hit.id || '') : '',
                  error: hit ? '' : [s.error, why].filter(Boolean).join(' | ').slice(0, 300), reconciled: !!hit,
                  foreignFetched: fetchedAll.length - fetched.length }, pairedItem: { item: 0 } }];
